private void radiusPulse(){
        this.quadSize = Mth.clamp(this.quadSize + this.radiusAmount, 1.0F, 1.5F);
        if (this.quadSize == 1.0F || this.quadSize == 1.5F) {
            this.setSprite(this.spriteSet.get(this.random));
            this.radiusAmount *= -1;
        }
    }

